// traçados especiais (planejadas, radiais, cidades antigas de ladeira)
const TRACADO_ESPECIAL = { 5300108: 'planejada', 1721000: 'planejada', 4115200: 'planejada', 3106200: 'diagonal', 5208707: 'radial', 1400100: 'radial', 3550308: 'radial', 3509502: 'radial', 4314902: 'radial', 3304557: 'organica', 2927408: 'organica', 2111300: 'organica', 2611606: 'organica', 1501402: 'organica', 2304400: 'grade', 4106902: 'diagonal' };
