  P.flor = Hh('fl') < 0.55 ? 1 + Math.floor(Hh('fl2') * 4) : 0; // 1 ipê amarelo · 2 ipê rosa · 3 flamboyant · 4 jacarandá
  // rotação da grade: aleatória por cidade; paralela à costa onde há mar perto; planejadas alinhadas
  let th = hashN('rot' + seed) * (Math.PI / 2);
  if (T_.alinhado) th = Hh('rot3') < 0.5 ? 0 : Math.PI / 12;
  else if (P.costa && Hh('al') < 0.85) th = Math.round(P.costa.ang / (Math.PI / 12)) * (Math.PI / 12) + (Hh('al2') - 0.5) * 0.12;
  P.th = th;
