function construirLayout(opts) {
  const prep = prepararLayout(opts);
  const urb = Cidade.urbanizar(prep.specs, TERRA, _fixos);
  const cidades = urb.cidades;
  for (const cid of cidades) if (cid.deslocada > 0) _fixos.set(cid.ibge, cid.centro); // praça deslocada fica onde está durante a sessão
  return finalizarLayout(prep, cidades, cidades.map((_, q) => q), urb);
}

/** Fatiado. Gerador: a cada cidade urbanizada não devolve nada que o chamador precise guardar, exceto nos marcos de progresso
    ({ parcial: () => layout das cidades prontas, feito, total } em 35% e 70% das casas); ao terminar devolve o layout completo. */
