reg({ id: 'cristo-redentor', nome: 'Cristo Redentor', categoria: 'famosa', tamanho: [4.5, 4.5, 7.5],
  apelidos: ['cristo redentor', 'cristo do rio', 'cristo do corcovado', 'o cristo', 'cristo', 'redentor', 'corcovado', 'cristo redentor do rio'],
  criar(K) {
    const m = K.estagio('morro', 0);
    m.cyl(2.3, 1.2, 1.6, 9, '#6aa24c', null, true);
    m.cyl(1.2, 0.9, 0.5, 9, '#a39f93', { y: 1.6 });
    const yS = (r) => (2.3 - r) / 1.1 * 1.6;
    [[0.5, 1.9], [1.4, 1.75], [2.3, 1.95], [3.3, 1.8], [4.2, 2.0], [5.1, 1.7], [5.9, 1.85]].forEach(([a, r], i) => arvore(m, Math.cos(a) * r, Math.sin(a) * r, 0.75 + (i % 3) * 0.1, yS(r)));
    const p = K.estagio('pedestal', 2.1);
    p.bx(-0.66, 2.1, -0.66, 0.66, 2.42, 0.66, '#b9b5a8'); p.bx(-0.52, 2.42, -0.52, 0.52, 3.2, 0.52, '#d9d5c8'); p.bx(-0.45, 3.2, -0.45, 0.45, 3.5, 0.45, '#c3bfb2');
    const c = K.estagio('corpo', 3.5);
    c.torno([[0.5, 3.5], [0.44, 4.4], [0.36, 5.6], [0.3, 6.5], [0.26, 6.9]], 8, '#eaefea');
    c.bx(-0.5, 6.4, -0.22, 0.5, 6.85, 0.22, '#eaefea');
    c.cyl(0.13, 0.12, 0.3, 6, '#dfe5df', { y: 6.8 }); c.esfera(0.27, '#eef2ee', { y: 7.2 }, 8, 6);
    const b = K.estagio('bracos', 6.4, 1.15);
    for (const sg of [-1, 1]) { b.tubo([sg * 0.42, 6.7, 0], [sg * 1.95, 6.58, 0], 0.2, 0.14, '#e4eae4', 6); b.bx(sg * 1.95 - 0.11, 6.4, -0.1, sg * 1.95 + 0.11, 6.64, 0.1, '#e4eae4'); }
    return K.montar();
  } });

