        s.bx(x0, 0.04, z0, x1, 0.2, z1, AZUL);
        s.bx(x0, 0.2, z0, x1, 0.29, z1, ROXO);
        s.bx(x0, 0.29, z0, x1, 0.325, z1, VERDE);
