      gotaLogo(s, { x: 0.59, y: 0.4, z: 0.845, s: 0.32 }, 0.04);
      // lateral direita: gota grande na parede
      gotaLogo(s, { x: 0.975, y: 0.5, z: 0.0, ry: PI / 2, s: 0.55 }, 0.05);
      // refletores no beiral
      for (const x of [-0.55, 0.0, 0.55]) { s.tubo([x, 1.25, 0.82], [x, 1.33, 1.0], 0.012, 0.012, '#1f242d', 4); s.cyl(0.04, 0.05, 0.07, 6, '#1f242d', { x, y: 1.27, z: 1.0, rx: PI / 2 + 0.6 }); }

