        const zz = 0.96 + (j - (2 - i) / 2) * 0.07 + 0.04; s.tubo([x0, y, zz], [x1, y, zz], 0.03, 0.03, i % 2 ? CZ : '#b8bec7', 5); s.tubo([x0, y, zz], [x0 + 0.04, y, zz], 0.034, 0.034, AZUL, 5);
