      s.bx(0.82, 0.13, 0.9, 1.02, 0.42, 1.1, BR); s.bx(0.9, 0.27, 0.9, 1.02, 0.39, 1.1, C.vidro); s.bx(0.82, 0.13, 0.9, 1.02, 0.19, 1.1, ROXO);
