        a.prisma([[-0.205, 0.846], [0.205, 0.846], [0.11, 0.8], [0, 0.78], [-0.11, 0.8]].map(f), T + 0.04, '#1e2430', { rx: PI / 2, z: -T / 2 - 0.02 });
        // punhos das mangas
