      s.bx(-1.1, 0, -1.1, 1.1, 0.06, 1.1, '#8cc866');                                   // gramado
      s.bx(0.12, 0.06, 0.8, 0.58, 0.075, 1.1, '#c0603a'); s.bx(0.02, 0.06, 0.98, 0.68, 0.075, 1.1, '#b3552f'); // terra vermelha
