      s.bx(-1.0, 0.06, -0.8, 1.0, 0.16, 0.83, '#56655b');                               // rodapé escuro
      s.bx(-0.47, 1.25, -0.83, 1.03, 1.31, 0.86, '#9aa89f');                            // laje do telhado
      // volume alto à esquerda com o logo redondo
      s.bx(-1.0, 1.25, -0.8, -0.5, 1.78, 0.8, '#7f8f84'); s.bx(-1.03, 1.78, -0.83, -0.47, 1.84, 0.86, '#5b6a60');
      s.bx(-1.0, 0.7, 0.8, -0.5, 1.25, 0.82, '#98a89c');
      for (const z of [-0.45, 0.1, 0.5]) s.bx(-1.02, 1.28, z - 0.09, -1.0, 1.7, z + 0.09, '#46575d');  // janelas altas na lateral
      s.cyl(0.19, 0.19, 0.03, 14, '#f3f4f6', { x: -0.75, y: 1.52, z: 0.8, rx: PI / 2 });
      m.cyl(0.165, 0.165, 0.045, 14, '#fff', { x: -0.75, y: 1.52, z: 0.8, rx: PI / 2 });
