      s.tubo([-0.75, 1.45, 0.86], [-0.75, 1.55, 0.86], 0.012, 0.012, '#4fa04a', 4); placa(s, [[0, 0], [0.05, 0.02], [0.09, 0.07], [0.04, 0.1], [0, 0.05]], 0.012, '#4fa04a', { x: -0.75, y: 1.55, z: 0.862 }); placa(s, [[0, 0], [-0.05, 0.02], [-0.09, 0.07], [-0.04, 0.1], [0, 0.05]], 0.012, '#6cc04a', { x: -0.75, y: 1.55, z: 0.862 });
      // faixa branca do letreiro (frente e fundo)
      for (const sg of [1, -1]) s.bx(-0.9, 0.745, sg > 0 ? 0.79 : -0.83, 0.9, 1.235, sg > 0 ? 0.83 : -0.79, '#f3f4f6');
      // varanda: laje branca, pilares, vidro com esquadria
