      for (const x of [-0.42, 0.14, 0.7, 1.0]) s.cyl(0.028, 0.028, 0.58, 6, '#c9ced6', { x, y: 0.06, z: 1.1 });
      s.bx(-0.45, 0.14, 0.8, 1.02, 0.62, 0.82, '#3f4d44'); s.bx(-0.4, 0.16, 0.82, 0.97, 0.6, 0.835, '#7fa2b8');
      for (let i = 0; i < 6; i++) s.bx(-0.4 + i * 0.1 - 0.008, 0.16, 0.835, -0.4 + i * 0.1 + 0.008, 0.6, 0.845, '#3f4d44');
      s.bx(0.36, 0.06, 0.82, 0.62, 0.62, 0.85, '#3f4d44'); s.bx(0.4, 0.1, 0.85, 0.58, 0.58, 0.86, '#9fc4dc');
      // porta na parte alta esquerda e janelas
