      // mastro com a bandeira do Brasil
      s.tubo([0.96, 0.06, 0.98], [0.96, 1.56, 0.98], 0.014, 0.014, '#c9ced6', 4); s.esfera(0.025, '#e8b84b', { x: 0.96, y: 1.58, z: 0.98 }, 4, 3);
      s.bx(0.6, 1.3, 0.97, 0.95, 1.52, 0.985, '#1f9d55');
      placa(s, [[-0.14, 0], [0, 0.085], [0.14, 0], [0, -0.085]], 0.012, '#ffd23f', { x: 0.775, y: 1.41, z: 0.985 });
