      s.bx(cx - 0.52, 0, -0.34, cx + 0.52, 0.5, 0.32, '#7a4f2e');
      s.bx(cx - 0.52, 0.18, -0.34, cx + 0.52, 0.22, 0.32, '#6a4226'); s.bx(cx - 0.52, 0.36, -0.34, cx + 0.52, 0.39, 0.32, '#8a5d37');
      s.bx(cx - 0.55, 0.5, -0.37, cx + 0.55, 0.56, 0.35, '#5fae45');
      for (const [x, z] of [[-0.4, 0.28], [-0.1, 0.3], [0.2, 0.3], [0.42, 0.26], [0.45, -0.2], [-0.42, -0.2]]) s.cone(0.04, 0.12, 4, '#4f9c3f', { x: cx + x, y: 0.55, z });
      // semente rachada na face da frente + raízes
      const zf = 0.32;
