      s.esfera(1, '#8a5a2b', { x: cx + 0.095, y: 0.31, z: zf, sx: 0.12, sy: 0.25, sz: 0.08 }, 7, 5);
      s.esfera(1, '#f0e1b0', { x: cx, y: 0.31, z: zf - 0.01, sx: 0.03, sy: 0.23, sz: 0.07 }, 5, 4);
      const raiz = '#e8d9b0';
      s.tubo([cx, 0.1, zf + 0.01], [cx - 0.02, 0.0, zf + 0.025], 0.026, 0.014, raiz, 4); s.tubo([cx - 0.01, 0.07, zf + 0.02], [cx - 0.26, 0.0, zf + 0.025], 0.02, 0.01, raiz, 4);
      s.tubo([cx + 0.01, 0.07, zf + 0.02], [cx + 0.26, 0.0, zf + 0.025], 0.02, 0.01, raiz, 4); s.tubo([cx - 0.01, 0.09, zf + 0.02], [cx - 0.12, 0.0, zf + 0.025], 0.014, 0.007, raiz, 4); s.tubo([cx + 0.01, 0.09, zf + 0.02], [cx + 0.12, 0.0, zf + 0.025], 0.014, 0.007, raiz, 4);
      // broto: caule curvo + 2 folhas enormes + botão
      const P = [[cx, 0.56, 0], [cx - 0.02, 0.8, 0], [cx + 0.02, 1.0, 0], [cx + 0.07, 1.16, 0]];
      for (let i = 0; i + 1 < P.length; i++) s.tubo(P[i], P[i + 1], 0.05 - i * 0.012, 0.05 - (i + 1) * 0.012, '#4f9c3f', 5);
