      s.com({ x: P[3][0], y: P[3][1] - 0.02, z: 0, ry: PI, rz: 0.4, rx: 0.0 }, (l) => { l.prisma(FOLHA, 0.035, '#4fa84a'); l.tubo([0, 0.02, 0], [0.6, 0.02, 0], 0.012, 0.008, '#3f8a38', 3); });
      s.cone(0.05, 0.2, 5, '#78cc55', { x: P[3][0], y: P[3][1] - 0.02, z: 0 });
