      s.bx(0.06, 0.04, 0.8, 0.9, 0.72, 0.83, '#1c2027'); s.bx(0.1, 0.08, 0.83, 0.5, 0.68, 0.845, VIDRO); s.bx(0.3 - 0.008, 0.08, 0.845, 0.3 + 0.008, 0.68, 0.855, '#1c2027');
      s.bx(0.56, 0.2, 0.83, 0.86, 0.6, 0.845, VIDRO);
      // andares de cima: paredes, lajes com sacada, guarda-corpo, vidros
      for (let i = 0; i < 3; i++) {
        const y0 = 1.25 + i * 0.33, y1 = y0 + 0.33;
        s.bx(-0.95, y0, -0.8, 0.95, y1, 0.72, i % 2 ? '#666d76' : GRAF2, true);
        s.bx(-0.99, y0, 0.7, 0.99, y0 + 0.035, 1.0, LAJE);
        s.bx(-0.99, y0 + 0.17, 0.98, 0.99, y0 + 0.185, 1.0, '#c9ced6');
        for (let k = 0; k <= 12; k++) s.bx(-0.97 + k * 0.1617, y0 + 0.035, 0.985, -0.955 + k * 0.1617, y0 + 0.17, 1.0, '#c9ced6');
        for (const x of [-0.6, 0.0, 0.6]) { s.bx(x - 0.24, y0 + 0.06, 0.72, x + 0.24, y0 + 0.31, 0.735, '#1c2027'); s.bx(x - 0.22, y0 + 0.08, 0.735, x + 0.22, y0 + 0.29, 0.745, VIDRO); s.bx(x - 0.008, y0 + 0.08, 0.745, x + 0.008, y0 + 0.29, 0.752, '#1c2027'); }
        for (const sg of [-1, 1]) for (const z of [-0.4, 0.1]) s.bx(sg > 0 ? 0.95 : -0.97, y0 + 0.08, z - 0.09, sg > 0 ? 0.97 : -0.95, y0 + 0.28, z + 0.09, VIDRO);
      }
