      s.bx(-0.99, TOPO, 0.96, 0.99, TOPO + 0.1, 1.0, GRAF2); s.bx(-0.99, TOPO, -0.83, -0.95, TOPO + 0.1, 1.0, GRAF2); s.bx(0.95, TOPO, -0.83, 0.99, TOPO + 0.1, 1.0, GRAF2); s.bx(-0.99, TOPO, -0.83, 0.99, TOPO + 0.1, -0.79, GRAF2);
