/* ================= letreiro ================= */
function luminancia(hex) { const n = parseInt(hex.replace('#', ''), 16), f = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }; return 0.2126 * f((n >> 16) & 255) + 0.7152 * f((n >> 8) & 255) + 0.0722 * f(n & 255); }
function normalizaHex(h) { h = String(h || '').trim(); if (/^#?[0-9a-f]{3}$/i.test(h)) h = h.replace('#', '').split('').map((x) => x + x).join(''); h = h.replace('#', ''); return /^[0-9a-f]{6}$/i.test(h) ? '#' + h.toLowerCase() : COR_PADRAO; }
function desenhaLetreiro(canvas, nome, cor, logo) {
  const g = canvas.getContext('2d'), claro = luminancia(cor) > 0.34, tinta = claro ? '#1e2430' : '#ffffff';
  g.fillStyle = cor; g.fillRect(0, 0, TW, TH);
  let x0 = 0; // com logo (16/10): quadrado branco à esquerda com a logo do cliente; o nome ocupa o resto
  if (logo && logo.width) { const L = TH - 20; g.fillStyle = '#ffffff'; g.fillRect(10, 10, L, L); g.drawImage(logo, 14, 14, L - 8, L - 8); x0 = L + 14; }
  g.strokeStyle = claro ? 'rgba(30,36,48,.28)' : 'rgba(255,255,255,.4)'; g.lineWidth = 4; g.strokeRect(8, 8, TW - 16, TH - 16);
  g.fillStyle = tinta; g.textAlign = 'center'; g.textBaseline = 'middle';
  const fam = '"Nunito", "Helvetica Neue", Helvetica, Arial, sans-serif', maxW = TW - 56 - x0, cx0 = x0 + (TW - x0) / 2;
  let px = 84; g.font = '900 ' + px + 'px ' + fam;
  while (g.measureText(nome).width > maxW && px > 30) { px -= 2; g.font = '900 ' + px + 'px ' + fam; }
  if (g.measureText(nome).width > maxW) { // nome enorme: encolhe na horizontal em vez de cortar
    g.save(); g.translate(cx0, TH / 2 + 3); g.scale(maxW / g.measureText(nome).width, 1); g.fillText(nome, 0, 0); g.restore();
  } else g.fillText(nome, cx0, TH / 2 + 3);
}
function letreiro(T, nome, cor, logoSrc) { // { mat, tex, pronto }
  if (typeof document === 'undefined') return { mat: new T.MeshBasicMaterial({ color: new T.Color(cor), toneMapped: false }), tex: null, pronto: Promise.resolve() };
  const cv = document.createElement('canvas'); cv.width = TW; cv.height = TH;
  let logo = null;
  desenhaLetreiro(cv, nome, cor, null);
  const tex = new T.CanvasTexture(cv); if ('colorSpace' in tex) tex.colorSpace = T.SRGBColorSpace; else tex.encoding = T.sRGBEncoding; tex.anisotropy = 4;
  // se a Nunito ainda não carregou, redesenha quando chegar
  try { if (document.fonts && document.fonts.check && !document.fonts.check('900 40px Nunito') && document.fonts.load) document.fonts.load('900 40px Nunito').then(() => { if (!tex.userData.liberada && document.fonts.check('900 40px Nunito')) { desenhaLetreiro(cv, nome, cor, logo); tex.needsUpdate = true; } }).catch(() => {}); } catch (e) { /* sem fonte, fica a sans-serif */ }
  tex.userData = tex.userData || {};
  // logo do cliente (opcional): URL ou imagem já carregada; redesenha quando chegar. Falhou? fica só o nome.
  let pronto = Promise.resolve();
  if (logoSrc) pronto = new Promise((ok) => {
    const usar = (img) => { logo = img; if (!tex.userData.liberada) { desenhaLetreiro(cv, nome, cor, logo); tex.needsUpdate = true; } ok(); };
    if (typeof logoSrc !== 'string') { usar(logoSrc); return; }
    const img = new Image(); img.crossOrigin = 'anonymous'; img.onload = () => usar(img); img.onerror = () => ok(); img.src = logoSrc;
  });
  return { mat: new T.MeshBasicMaterial({ map: tex, toneMapped: false }), tex, pronto };
}

/* ================= API ================= */
const ids = new Set(TIPOS.map((t) => t.id));
/* ESPECIAIS (16/10): loja feita sob medida para um cliente. Lojas.registrarEspecial(id, def) com
   def = { tipo?, parede?: hex, fachada?(s, m, ctx), icone(s, m, ctx), anima?: 'giro' | 'flutua' | 'pulo', topo?: altura extra }
   s = estágio com cores fixas, m = estágio que recebe a COR DA MARCA. ctx = { C, PI, ROOF, LOTE, SW, SH, SY, SZ, fachadaPadrao(s, m, parede) }.
   fachada (opcional) substitui o corpo inteiro (y = 0 é o chão do lote); icone fica sobre o telhado (y = 0 é o telhado).
   Sem def (ou id desconhecido) a loja sai do tipo normal: nada muda para quem não tem especial. */
