  const nome = String(o.nome === undefined || o.nome === null || o.nome === '' ? TIPOS.find((t) => t.id === tipo).nome : o.nome).trim().slice(0, 40);
  const esp = o.especial && ESPECIAIS[o.especial] ? String(o.especial) : null;
  const A = o.A || aPadrao(T), c = cacheDe(T, A, o.mat), geo = geometriasDoTipo(T, c, tipo, esp);
  const root = new T.Group(), estagios = [], mats = [];
  const matMarca = new T.MeshStandardMaterial({ color: A(cor), roughness: 0.9, flatShading: true }); mats.push(matMarca);
  const mesh = (g, m) => { const x = new T.Mesh(g, m); x.castShadow = true; x.receiveShadow = true; x.frustumCulled = false; return x; };
  // corpo (sobe do chão)
  const sc = new T.Group(); sc.name = 'estagio:corpo';
  sc.add(mesh(geo.corpo, c.mat)); if (geo['corpo-marca']) sc.add(mesh(geo['corpo-marca'], matMarca));
  const L = letreiro(T, nome, cor, o.logo); mats.push(L.mat);
  for (const sg of [1, -1]) { const p = new T.Mesh(c.plano, L.mat); p.position.set(0, SY, sg * SZ); if (sg < 0) p.rotation.y = PI; p.name = 'loja:letreiro'; sc.add(p); }
  root.add(sc); estagios.push({ g: sc, nome: 'corpo', delay: 0 });
