  const box = (x0, y0, z0, x1, y1, z1, hex) => { const c = A(hex); const v = [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], f = [[4, 5, 6, 7], [1, 0, 3, 2], [0, 4, 7, 3], [5, 1, 2, 6], [3, 7, 6, 2], [0, 1, 5, 4]]; for (const q of f) for (const k of [0, 1, 2, 0, 2, 3]) { P.push(...v[q[k]]); C.push(c.r, c.g, c.b); } };
  const w = Math.min(tam[0], 6) / 2, d = Math.min(tam[1], 6) / 2;
