/* ---------- posição ---------- */
const OB_POS = new Map(), OB_G = new Map(); // ibge → {x, y, yaw, r} · ibge → THREE.Group
const OB_ANG = Array.from({ length: 24 }, (_, i) => i * 15).sort((a, b) => { const d = (x) => Math.min(Math.abs(x - 225), 360 - Math.abs(x - 225)); return d(a) - d(b) || a - b; }).filter((g) => g !== 45).concat([45]); // sudoeste primeiro, depois ao redor; nordeste (hospital Figo) por último
function obraRaio(id) { const a = obraTam(id), b = obraTam('canteiro'), t = [Math.max(a[0], b[0]), Math.max(a[1], b[1])]; return Math.min(8, Math.hypot(t[0], t[1]) / 2 + 0.4); }
