  let p = OB_POS.get(c.ibge); if (p) return p;
  const o = OB.get(c.ibge), r = obraRaio(o.id), terra = window.__terraDe(c), Y = mundo ? mundo.relY : () => 0;
  if (FG && FG_IB.has(c.ibge)) figoPos(c); // o hospital desta cidade reserva o lugar dele primeiro
  const vizFg = []; if (FG) for (const q of ORDEM) { if (q === c || !FG_IB.has(q.ibge)) continue; if (Math.hypot(q.cx - c.cx, q.cy - c.cy) > q.rs + c.rs + r + 40) continue; const pq = figoPos(q); if (!pq.dentro) vizFg.push(pq); } // hospitais das cidades vizinhas
  const terraCt = (px, py) => { let t = TERRA(px, py) ? 1 : 0; if (!t) return 0; for (let k = 0; k < 8; k++) { const a = k * Math.PI / 4; if (TERRA(px + r * 0.85 * Math.cos(a), py + r * 0.85 * Math.sin(a))) t++; } return t; };
  const colideHosp = (px, py) => { if (FG) for (const q of [...FG_POS.values(), ...vizFg]) if (Math.hypot(px - q.x, py - q.y) < r + 3.2 + 0.6) return true; for (const q of OB_POS.values()) if (Math.hypot(px - q.x, py - q.y) < r + q.r + 0.6) return true; return false; };
  const colideCid = (px, py) => { for (const q of ORDEM) { if (q === c) continue; const dx = px - q.cx; if (dx > q.rs + r + 12 || dx < -q.rs - r - 12) continue; if (Math.hypot(dx, py - q.cy) < q.rs + r + 0.6) return true; } return false; };
  const desnivel = (px, py) => { let mn = 1e9, mx = -1e9; for (const [dx, dy] of [[0, 0], [r * 0.7, 0], [-r * 0.7, 0], [0, r * 0.7], [0, -r * 0.7]]) { const y = Y(px + dx, py + dy); if (y < mn) mn = y; if (y > mx) mx = y; } return mx - mn; };
