  const d = el('div', 'obra-lin' + (e.pronto ? ' ok' : '')), t = el('div', 'obra-tx');
  d.append(el('span', 'obra-ic', e.pronto ? '✅' : '🏗️'));
  if (e.pronto) { t.append(el('b', '', e.o.nome + ' inaugurado'), el('i', '', `a cidade passou de ${fmtN(e.o.alvo)} moradores`)); }
  else { t.append(el('b', '', 'Obra: ' + e.o.nome), el('i', '', `${e.pct}% · faltam ${plural(e.faltam, 'morador', 'moradores')} (meta ${fmtN(e.o.alvo)})`)); }
  d.append(t);
