  st.append(stat(fmtN(c.n), c.n === 1 ? 'casa' : 'casas'), stat(fmtN(m.predios), m.predios === 1 ? 'prédio' : 'prédios'), stat('#' + fmtN(c.q + 1), 'no Brasil'), stat('#' + fmtN(c.rUF), 'em ' + c.uf));
  cart.append(st);
