  { const fg = figoLinhaCidade(c); if (fg) cart.append(fg); }
  cartaoCidadeExtras(cart, c);
  cart.append(botoes(btn('ver no mapa', () => { if (mundo) mundo.voarCidade(garantirCidade(c)); else irLeve(c.cx, c.cy, Math.max(40, c.rs * 6)); }, 'prim')));
  return cart;
