  const T = el('div', 'top5'); T.append(el('div', 'rot', 'maiores cidades'));
  top.slice(0, 5).forEach((c, i) => { const r = el('button', 'lin2'); r.type = 'button'; r.append(el('span', 'pos', String(i + 1)), el('span', 'nm', c.nome), el('span', 'nn', fmtN(c.n))); r.onclick = () => cartaoCidade(c); T.append(r); });
  cart.append(T);
