    const k = CIDS.find((x) => x.c === sel.c);
    if (k) { const R = Math.max(k.Rm + 7, k.real * 1.08 + 4); if (R < 80) { ring.hidden = false; ring.style.width = ring.style.height = (R * 2).toFixed(1) + 'px'; ring.style.transform = `translate(${(k.sx - R).toFixed(1)}px,${(k.sy - R).toFixed(1)}px)`; return; } }
