    const e = $('etq'), p = mundo.projetarCasa(sel.casa, 1.3), vis = p.ok && q.h < 140;
    if (vis) { const y = Math.max(p.y - 14, UI.topo + 70); e.style.transform = `translate(${p.x.toFixed(1)}px,${y.toFixed(1)}px) translate(-50%,-100%)`; }
