    mola((x) => { segs.forEach((i) => { i.style.width = (+i.dataset.w * x).toFixed(2) + '%'; }); }, 120, 13);
    ks.forEach((k) => { const li = el('li', q[k] ? '' : 'zero'), d = el('u'); d.style.background = QCOR[k]; li.append(d, el('span', '', QNOME[k]), el('b', '', q[k] ? '+' + q[k] : '0')); leg.append(li); });
