  const alvo = k > 1 ? Math.min(1, (nv - ini + frac) / (k - 1)) * 100 : 100;
  mola((x) => { fill.style.width = (alvo * x).toFixed(2) + '%'; if (atual[0]) atual[0].style.transform = `translateY(${((1 - Math.min(1.2, x)) * 12).toFixed(1)}px) scale(${(0.82 + 0.18 * x).toFixed(3)})`; }, 130, 11);
  const p = el('p', 'falta-nv');
