  const mk = (esc, rot, pos, de, qual) => { const f = faltaPara(gi, esc), x = el('button', 'tt' + (f.ok ? ' ok' : '')); x.type = 'button'; x.setAttribute('aria-label', `ver o ranking: ${rot}, posição ${pos}`);
    x.append(el('span', 'te', rot), el('b', 'tn', '#' + fmtN(pos)), el('span', 'td', de), el('i', 'tf', f.txt)); x.onclick = () => abrirRanking({ gi, esc: qual }); return x; };
  g.append(mk('cid', 'cidade', posNaLista(gi, 'cid'), 'de ' + fmtN(c.n) + ' em ' + c.nome, 'cid'), mk('est', 'estado', posNaLista(gi, 'est'), 'de ' + fmtN(e.nres) + ' em ' + c.uf, 'est'), mk('br', 'Brasil', posNaLista(gi, 'br'), 'de ' + fmtN(NM), 'br'));
