  const cart = el('div', 'cart pessoa' + (ehFund ? ' fund' : '') + (k ? ' cg' + k : ''));
  const cab = el('div', 'cab');
  { const nm = el('div', 'nome', '@' + h); if (h.length > 12) nm.style.fontSize = 'calc(clamp(24px, 7.4vw, 32px) * ' + Math.max(0.55, 12 / h.length).toFixed(2) + ')'; nm.style.whiteSpace = 'nowrap'; cab.append(nm); } cart.append(cab);
  const onde = el('div', 'onde'); const lk = el('button', 'lk'); lk.type = 'button'; lk.append(el('b', '', c.nome)); lk.onclick = () => cartaoCidade(c);
  onde.append(lk, el('span', '', '· ' + c.uf));
  if (prov) onde.append(el('span', 'pill prov', 'casa provisória'));
  cart.append(onde);
  { const fs = figoSelo(h, c); if (fs) cart.append(fs); }
  { const sa = seloAlta(gi); if (sa) cart.append(sa); }
  cart.append(botaoStoryGrande(gi, h));
  if (prov) cart.append(el('p', 'nota', 'você só disse o estado, então a casa ficou na capital. comenta o nome da sua cidade no último post e ela muda.'));
  const pq = qDe(gi); pq.catch(() => {});
  const b1 = blocoComposicao(pq, t); PQ_GI.set(b1, gi);
  cart.append(blocoCargo(k, c, ehFund), blocoPontos(t, s), b1, blocoEscada(t, nv), blocoTrio(gi, c));
  const dp = disputa(gi), db = el('div', 'disp' + (dp.topo ? ' topo' : '')); db.append(el('b', '', dp.txt)); if (dp.sub) db.append(el('span', '', dp.sub)); cart.append(db);
  if (PEMM[gi]) cart.append(el('p', 'quando', 'casa criada em ' + quandoBRT(PEMM[gi])));
  const ba = bk('acoes-bk', 'como ganhar mais pontos', 'toque e faça'); ba.append(cartoesAcao({ gi, h, pq }));
  const mais = btn('como funciona tudo isso?', () => abrirComo(), 'mini como-lk'); ba.append(mais);
