/* ---------- ir para o mapa ---------- */
function paraMapa(fn) { fecharDados(); if (window.__fecharLojas) window.__fecharLojas(); if (window.__fecharBrasilia) window.__fecharBrasilia(); if (window.__fecharRanking) window.__fecharRanking(); if (window.__fecharComo) window.__fecharComo(); const ok = () => { if (pronto && (mundo || L2.ativo)) fn(); else setTimeout(ok, 200); }; ok(); }
