function verPessoa(gi) { paraMapa(() => mostrarCasa(USR[gi], gi)); }

/* ---------- imagens para story (1080x1920) ---------- */
function tx(g, s, x, y, px, o = {}) {
  g.font = `900 ${px}px Nunito, system-ui, sans-serif`; g.textAlign = o.al || 'left'; g.textBaseline = 'alphabetic';
  if (o.out) { g.lineWidth = Math.max(4, px * 0.2); g.strokeStyle = '#000'; g.strokeText(s, x, y); }
  g.fillStyle = o.cor || TINTA_; g.fillText(s, x, y);
}
function ajusta(g, s, px, max) { g.font = `900 ${px}px Nunito, system-ui, sans-serif`; const w = g.measureText(s).width; return w > max ? Math.floor(px * max / w) : px; }
function novoCanvas(titulo, sub) {
  const c = document.createElement('canvas'); c.width = 1080; c.height = 1920; const g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, 0, 1920); gr.addColorStop(0, '#b3d1ee'); gr.addColorStop(0.55, '#e6ebea'); gr.addColorStop(1, '#cfe3c4'); g.fillStyle = gr; g.fillRect(0, 0, 1080, 1920);
  g.lineJoin = 'round'; g.lineCap = 'round';
  const T = titulo.toUpperCase(); tx(g, T, 540, 205, ajusta(g, T, 130, 960), { al: 'center', out: true, cor: '#fff' });
  if (sub) tx(g, sub, 540, 280, ajusta(g, sub, 46, 940), { al: 'center', out: true, cor: AMARELO_ });
  return { c, g };
}
function caixa(g, x, y, w, h, fill = '#fff', r = 44, borda = 10) {
  g.save(); g.shadowColor = 'rgba(30,36,48,.35)'; g.shadowOffsetY = 14; g.beginPath(); g.roundRect(x, y, w, h, r); g.fillStyle = fill; g.fill(); g.restore();
  g.beginPath(); g.roundRect(x, y, w, h, r); g.lineWidth = borda; g.strokeStyle = TINTA_; g.stroke();
}
function rodapeImg(g) {
  caixa(g, 250, 1722, 580, 96, '#fff', 48, 8); tx(g, 'naoeummapa.vercel.app', 540, 1788, ajusta(g, 'naoeummapa.vercel.app', 44, 520), { al: 'center' });
  tx(g, '@naoeummapa', 540, 1880, 46, { al: 'center', out: true, cor: '#fff' });
}
function barraImg(g, x, y, w, h, p) {
  g.beginPath(); g.roundRect(x, y, w, h, h / 2); g.fillStyle = '#fff'; g.fill(); g.lineWidth = 7; g.strokeStyle = TINTA_; g.stroke();
  if (p > 0.001) { g.beginPath(); g.roundRect(x + 4, y + 4, Math.max(h - 8, (w - 8) * Math.min(1, p)), h - 8, (h - 8) / 2); g.fillStyle = AMARELO_; g.fill(); g.lineWidth = 5; g.stroke(); }
}
function bolaImg(g, x, y, r, n) { g.beginPath(); g.arc(x, y, r, 0, 7); g.fillStyle = AMARELO_; g.fill(); g.lineWidth = 7; g.strokeStyle = TINTA_; g.stroke(); tx(g, String(n), x, y + r * 0.38, r * 1.1, { al: 'center' }); }
function wrap(g, s, x, y, px, max, o = {}) {
  g.font = `900 ${px}px Nunito, system-ui, sans-serif`; let l = '', yy = y;
  for (const w of s.split(' ')) { const t = l ? l + ' ' + w : w; if (g.measureText(t).width > max && l) { tx(g, l, x, yy, px, o); l = w; yy += px * 1.2; } else l = t; }
  if (l) tx(g, l, x, yy, px, o); return yy;
}
function listaImg(titulo, sub, linhas, opt = {}) { // linhas: [{n, a, b, v, p}]
  const { c, g } = novoCanvas(titulo, sub), N_ = linhas.length, y0 = 340, alt = Math.min(opt.alt || 128, Math.floor(1330 / N_)), H = N_ * alt + 40;
  caixa(g, 50, y0 - 20, 980, H, '#fff', 56);
  linhas.forEach((l, i) => {
    const y = y0 + 10 + i * alt, cy = y + 40;
    bolaImg(g, 112, cy, 34, l.n);
    g.font = '900 56px Nunito, system-ui, sans-serif'; const vw = l.v ? g.measureText(l.v).width : 0;
    tx(g, l.a, 170, cy + 14, ajusta(g, l.a, 52, 810 - vw - 20));
    if (l.v) tx(g, l.v, 990, cy + 16, 56, { al: 'right' });
    if (l.b) tx(g, l.b, 170, cy + 54, ajusta(g, l.b, 34, 800), { cor: '#5d6b7e' });
    if (l.p != null) barraImg(g, 170, cy + 66, 820, 20, l.p);
  });
  rodapeImg(g); return c;
}
function imgPlacar(N) {
  const { c, g } = novoCanvas('placar', 'o mapa agora · Dia ' + N.dia), p = N.placar; caixa(g, 50, 330, 980, 1320, '#fff', 56);
  const s = fmtN(p.casas); tx(g, s, 540, 780, ajusta(g, s, 330, 900), { al: 'center' }); tx(g, 'casas no mapa', 540, 890, 80, { al: 'center', cor: '#5d6b7e' });
  [[fmtN(p.cidades), 'cidades'], [`${p.estados}/${p.estadosTotal}`, 'estados'], PD ? [fmtN(PD_TOTAL_S()), 'pontos da semana'] : ['Dia ' + N.dia, 'agora']].forEach(([v, r], i) => { const x = 215 + i * 325; tx(g, v, x, 1330, ajusta(g, v, 84, 290), { al: 'center' }); wrap(g, r, x, 1396, 40, 290, { al: 'center', cor: '#5d6b7e' }); });
  rodapeImg(g); return c;
}
function imgCobertura(N) {
  const { c, g } = novoCanvas('cobertura', 'quanto do Brasil já tem casa'); caixa(g, 50, 330, 980, 1320, '#fff', 56);
  const sp = pct(N.placar.pctMun); tx(g, sp, 540, 560, ajusta(g, sp, 230, 900), { al: 'center' }); tx(g, `dos ${fmtN(N.placar.municipios)} municípios têm casa`, 540, 640, 46, { al: 'center', cor: '#5d6b7e' });
  const vb = N.mapa.vb, sc = Math.min(900 / vb[2], 860 / vb[3]), cor = corMapa(N), w = vb[2] * sc;
  g.save(); g.translate(540 - w / 2, 700); g.scale(sc, sc); g.translate(-vb[0], -vb[1]);
  for (const e of N.estados) { g.fillStyle = cor(e.pct); const pa = new Path2D(N.mapa.d[e.uf]); g.fill(pa); g.lineWidth = 9; g.strokeStyle = TINTA_; g.stroke(pa); }
  g.restore();
  tx(g, 'quanto mais amarelo, mais cidades do estado têm casa', 540, 1600, 36, { al: 'center', cor: '#5d6b7e' });
  rodapeImg(g); return c;
}
const imgCidades = (N) => { const ord = cidadesRank(N, 10), mx = ord[0].v || 1; return listaImg('quem mais engaja', PD ? 'cidades por pontos da semana' : 'cidades por casas', ord.map((x, i) => ({ n: i + 1, a: `${x.nome} · ${x.uf}`, v: fmtN(x.v), b: x.pref ? '🏛 @' + x.pref : '🚩 @' + x.fund, p: x.v / mx }))); };
function imgGuerra(N) {
  const ord = estadosRank(N).slice(0, 10), mx = ord[0].v || 1;
  return listaImg('guerra de estados', PD ? 'pontos da semana' : 'casas no mapa', ord.map((e, i) => ({ n: i + 1, a: e.nome, v: fmtN(e.v), b: e.gov ? '👑 @' + e.gov : '', p: e.v / mx })));
}
function imgCrescimento(N) {
  const { c, g } = novoCanvas('crescimento', 'casas por dia'); caixa(g, 50, 330, 980, 1320, '#fff', 56);
  const cr = N.crescimento, mx = Math.max(...cr.map((x) => x.casas)), n = cr.length, w = 860 / n, base = 1400, H = 760;
  cr.forEach((x, i) => { const cx = 110 + w * i + w / 2, bw = Math.min(210, w * 0.62), h = Math.max(10, x.casas / mx * H); g.beginPath(); g.roundRect(cx - bw / 2, base - h, bw, h, 26); g.fillStyle = AMARELO_; g.fill(); g.lineWidth = 8; g.strokeStyle = TINTA_; g.stroke(); tx(g, fmtN(x.casas), cx, base - h - 24, ajusta(g, fmtN(x.casas), 64, w - 10), { al: 'center' }); tx(g, 'Dia ' + x.dia, cx, base + 66, 54, { al: 'center' }); tx(g, fmtN(x.cidades) + ' cidades', cx, base + 116, 38, { al: 'center', cor: '#5d6b7e' }); });
  rodapeImg(g); return c;
}
function imgFundadas(N) {
  const f = N.fundadasHoje, { c, g } = novoCanvas('fundadores de hoje', `cidades novas no Dia ${f.dia}`); caixa(g, 50, 330, 980, 1320, '#fff', 56);
  const s = fmtN(f.total); tx(g, s, 540, 590, ajusta(g, s, 250, 900), { al: 'center' }); tx(g, `cidades com fundador novo · ${fmtN(f.casas)} casas`, 540, 670, 46, { al: 'center', cor: '#5d6b7e' });
  const top = f.top.slice(0, 8);
  top.forEach((x, i) => { const y = 730 + i * 112, t = `${x.nome} · ${x.uf}`; bolaImg(g, 112, y + 36, 30, i + 1); tx(g, t, 170, y + 36, ajusta(g, t, 46, 640)); tx(g, String(x.n), 990, y + 38, 52, { al: 'right' }); tx(g, '🚩 @' + x.fund, 170, y + 78, ajusta(g, '🚩 @' + x.fund, 32, 700), { cor: '#5d6b7e' }); });
  rodapeImg(g); return c;
}
async function imagemBloco(id) {
  const N = NUM.dados, b = BLOCOS.find((x) => x.id === id); if (!b) return null;
  try { await document.fonts.load('900 40px Nunito'); } catch (e) { /* segue */ }
  return b.img(N);
}
async function entregarImagem(c, nome, texto) { // compartilha a imagem (folha de compartilhar do celular) ou baixa o PNG
  const blob = await new Promise((ok) => c.toBlob(ok, 'image/png')), arq = new File([blob], nome, { type: 'image/png' });
  try { if (navigator.canShare && navigator.canShare({ files: [arq] })) { await navigator.share({ files: [arq], title: 'naoeummapa', text: texto || 'olha o mapa do @naoeummapa' }); return; } } catch (e) { if (e && e.name === 'AbortError') return; }
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = nome; document.body.append(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000); toast('imagem baixada');
}
async function compartilharBloco(id, botao) {
  const t0 = botao && botao.querySelector('span'); if (t0) t0.textContent = 'gerando…';
  try { const c = await imagemBloco(id); if (!c) return; await entregarImagem(c, `naoeummapa-${id}-dia${D.dia}.png`); }
  finally { if (t0) t0.textContent = 'compartilhar'; }
}

/* ---------- a aba ---------- */
function carregarNumeros() {
  if (NUM.dados) return Promise.resolve(NUM.dados);
  if (!NUM.carregando) { const m = document.querySelector('meta[name="numeros"]'); NUM.carregando = fetch(m ? m.content : 'numeros.json').then((r) => r.json()).then((j) => (NUM.dados = j)); }
  return NUM.carregando;
}
function montarDados(N) {
  const box = $('dados-corpo'); box.replaceChildren(); for (let i = BLOCOS.length - 1; i >= 0; i--) if (!BLOCOS[i].brasilia) BLOCOS.splice(i, 1);
  box.append(blocoPlacar(N), blocoGuerra(N), blocoCidades(N), blocoCobertura(N), blocoCrescimento(N), blocoFundadas(N)); if (OB.size) box.append(blocoObras());
  box.append(el('p', 'fonte', `Dia ${N.dia} · população: IBGE · cada casa é um seguidor que comentou o nome da cidade no @naoeummapa`));
}
let dadosAberto = false;
async function abrirDados(bloco) {
  if (window.__fecharLojas) window.__fecharLojas(); if (window.__fecharBrasilia) window.__fecharBrasilia(); if (window.__fecharRanking) window.__fecharRanking();
  const box = $('dados'); dadosAberto = true; box.hidden = false; document.body.classList.add('dados-on'); box.scrollTop = 0;
  try { history.replaceState(null, '', '#dados'); } catch (e) { /* file:// */ }
  if (!$('dados-corpo').firstChild) $('dados-corpo').append(el('p', 'carr', 'carregando os números…'));
  rootAtual = 'dados';
  try { const N = await carregarNumeros(); if (!BLOCOS.some((b) => !b.brasilia)) montarDados(N); } catch (e) { $('dados-corpo').replaceChildren(el('p', 'carr', 'não consegui carregar os números. tenta de novo.')); return; }
  if (bloco) { const a = $('b-' + bloco); if (a) a.scrollIntoView(); }
}
function fecharDados() {
  if (!dadosAberto) return; dadosAberto = false; $('dados').hidden = true; document.body.classList.remove('dados-on');
  try { if (location.hash === '#dados') history.replaceState(null, '', location.pathname + location.search); } catch (e) { /* ok */ }
}
$('abrirDados').addEventListener('click', () => abrirDados());
$('fecharDados').addEventListener('click', () => fecharDados());
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && dadosAberto) { fecharDados(); e.stopImmediatePropagation(); } }, true);
addEventListener('hashchange', () => { if (location.hash === '#dados') abrirDados(); else fecharDados(); });
Object.assign(window.__site, { abrirDados, fecharDados, imagemBloco, numeros: () => NUM.dados, blocos: () => BLOCOS.map((b) => b.id) });
abasDe('dados');
if (location.hash === '#dados' || new URLSearchParams(location.search).get('aba') === 'dados') abrirDados();

/* seletor ranking | Brasília | dados no topo de cada aba (só com pontos) */
function abasDe(cur) {
  if (!PD) return; const topo = $(cur + '-topo'); if (!topo || topo.querySelector('.abas')) return;
  const nav = el('nav', 'abas');
  const itens = [['ranking', 'ranking', () => abrirRanking()], ['brasilia', 'Brasília', () => abrirBrasilia()], ['dados', 'dados', () => abrirDados()]];
  if (lojasVigentes().length) itens.push(['lojas', 'Lojas', () => abrirLojas()]); // 4ª aba (lojas-hub.js): só com loja vigente; o pontinho pulsa enquanto houver +pts a ganhar
  for (const [id, rot, abre] of itens) { const b = el('button', id === cur ? 'on' : '', rot); b.type = 'button'; if (id !== cur) b.onclick = abre; if (id === 'lojas') { b.classList.add('tem-lojas'); b.append(el('i', 'selo-pt')); } nav.append(b); }
  nav.style.setProperty('--n', itens.length); if (itens.length > 3) nav.classList.add('quatro'); topo.append(nav); if (window.__lojasSelo) window.__lojasSelo();
}

/* ===== v2/site/src/brasilia.js ===== */
/* Aba BRASÍLIA ("quem engaja manda"): contagem regressiva do mandato, presidente, senadores, governadores e a guerra de estados. Só existe com pontos (dados.js › P).
   Reaproveita bloco(), as imagens 1080x1920 e o compartilhar de dados.js; os dados vêm dos arrays de site.js (PRESI, SENI, GOVI, UFS, PSEM…). */
let brAberto = false, brMontado = false, brTimer = 0;
const FIM_MS = () => PD.fim * 1000, INI_MS = () => PD.ini * 1000;
function dhms(ms) { if (ms <= 0) return 'fechou'; const s = Math.floor(ms / 1000), d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), x = s % 60; return d > 0 ? `${d}d ${p2(h)}h ${p2(m)}min` : `${h}h ${p2(m)}min ${p2(x)}s`; }
const fracMandato = () => Math.max(0, Math.min(1, (Date.now() - INI_MS()) / (FIM_MS() - INI_MS())));
const linhaGente = (gi, i, sub) => { // linha clicável de uma pessoa com cargo
  const c = LISTA[CID_DE[gi]], r = el('button', 'lr'); r.type = 'button'; r.onclick = () => verPessoa(gi);
  const l1 = el('div', 'l1'); l1.append(el('span', 'pos', String(i + 1)), el('span', 'nm', '@' + USR[gi]), chipUf(c.uf), el('b', 'vl', fmtN(PSEM[gi])));
  r.append(l1, el('div', 'l2', sub || c.nome + ' · ' + plural(PTOT[gi], 'ponto no total', 'pontos no total'))); return r;
};
function listaComMais(gis, mk, mostra) {
  const L = el('div', 'lista'), wrap = el('div'); gis.slice(0, mostra).forEach((g, i) => L.append(mk(g, i))); wrap.append(L);
  if (gis.length > mostra) wrap.append(MAIS(0, gis.length, () => gis.slice(mostra).forEach((g, i) => L.append(mk(g, i + mostra)))));
  return wrap;
}

