/* ---------- a aba ---------- */
function montarBrasilia() {
  const box = $('brasilia-corpo'); box.replaceChildren(); for (let i = BLOCOS.length - 1; i >= 0; i--) if (BLOCOS[i].brasilia) BLOCOS.splice(i, 1);
  rootAtual = 'brasilia'; bloco.brasilia = true;
  box.append(blocoMandato(), blocoPresidente(), blocoSenadores(), blocoGovernadores(), blocoGuerra(null, 'br-guerra'));
  bloco.brasilia = false; rootAtual = 'dados';
  box.append(el('p', 'fonte', `mandato ${PD.mand} · cargos ao vivo por pontos da semana · desempate: casa mais antiga`));
  brMontado = true; abasDe('brasilia');
}
function atualizarRelogio() { const r = document.querySelector('#brasilia .relogio'); if (r) r.textContent = dhms(FIM_MS() - Date.now()); }
function abrirBrasilia(bloco_) {
  if (!PD) return; fecharDados(); if (window.__fecharLojas) window.__fecharLojas(); if (window.__fecharRanking) window.__fecharRanking();
  const box = $('brasilia'); brAberto = true; box.hidden = false; document.body.classList.add('dados-on'); box.scrollTop = 0;
  try { history.replaceState(null, '', '#brasilia'); } catch (e) { /* file:// */ }
  if (!brMontado) montarBrasilia();
  clearInterval(brTimer); brTimer = setInterval(atualizarRelogio, 1000); atualizarRelogio();
  if (bloco_) { const a = $('b-' + bloco_); if (a) a.scrollIntoView(); }
}
function fecharBrasilia() {
  if (!brAberto) return; brAberto = false; $('brasilia').hidden = true; document.body.classList.remove('dados-on'); clearInterval(brTimer);
  try { if (location.hash === '#brasilia') history.replaceState(null, '', location.pathname + location.search); } catch (e) { /* ok */ }
}
if (PD) {
  $('abrirBrasilia').addEventListener('click', () => abrirBrasilia());
  $('fecharBrasilia').addEventListener('click', () => fecharBrasilia());
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && brAberto) { fecharBrasilia(); e.stopImmediatePropagation(); } }, true);
  addEventListener('hashchange', () => { if (location.hash === '#brasilia') abrirBrasilia(); else fecharBrasilia(); });
  Object.assign(window.__site, { abrirBrasilia, fecharBrasilia }); window.__fecharBrasilia = fecharBrasilia;
  if (location.hash === '#brasilia' || new URLSearchParams(location.search).get('aba') === 'brasilia') abrirBrasilia();
} else { const b = $('abrirBrasilia'); if (b) b.hidden = true; }

