function lojasVigentes() { const h = hojeBRT(); return LJ.filter((l) => l.desde <= h && l.ate >= h); }
const LH = { aberto: false, montado: false, filtro: '', busca: '', limite: 40, e: {} };
const lojaUf = (l) => { const c = POR_IBGE.get(l.ibge); return c ? c.uf : ''; };
